import{_ as e,o,c as r,a3 as d}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Marcar o endereço editado na minuta","description":"","frontmatter":{"title":"Marcar o endereço editado na minuta","id":"eproc-marcar-endereco-editado","plataforma":"eproc","grupo":"Árvore e minuta","plano":"free","desde":"1.13.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-marcar-endereco-editado"}]]},"headers":[],"relativePath":"funcionalidades/eproc-marcar-endereco-editado.md","filePath":"funcionalidades/eproc-marcar-endereco-editado.md"}'),i={name:"funcionalidades/eproc-marcar-endereco-editado.md"};function s(n,a,t,c,l,u){return o(),r("div",null,a[0]||(a[0]=[d('<h1 id="marcar-o-endereco-editado-na-minuta" tabindex="-1">Marcar o endereço editado na minuta <a class="header-anchor" href="#marcar-o-endereco-editado-na-minuta" aria-label="Permalink to &quot;Marcar o endereço editado na minuta&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Quando você corrige o endereço de um destinatário na minuta, quase sempre é porque vai usá-lo. Assim que o eproc salva a edição e atualiza a lista de endereços, o endereço editado já aparece marcado, sem precisar clicar na caixa dele.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, na seção &quot;Destinatário&quot; do cadastro e da edição de minuta.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Na lista de endereços de um destinatário, clique no lápis &quot;Editar Endereço&quot;.</li><li>Corrija os dados e clique em &quot;Salvar&quot;.</li><li>Quando a lista for atualizada, a caixa do endereço editado estará marcada. Ao lado dele aparece o logo do eploc; passe o mouse sobre ele para ver o aviso de que foi o eploc que marcou o endereço.</li><li>Se não for usar o endereço, é só desmarcar a caixa. O logo some.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Se você cancelar a edição, nada é marcado.</li><li>Se o endereço já estava marcado, o eproc o desmarca ao salvar a edição. O eploc o marca de novo, e o aviso do logo diz isso.</li><li>Endereços incluídos pelo botão &quot;Endereço&quot; não são marcados automaticamente.</li></ul>',11)]))}const h=e(i,[["render",s]]);export{m as __pageData,h as default};
